const APP_KEY = "hunter-fit-pro";
const USERS_KEY = APP_KEY + ":accounts";
const SESSION_KEY = APP_KEY + ":session";
const SHOP_KEY = APP_KEY + ":shop";
const UPI_ID = "ijatin56@ybl";
const SHOP_NAME = "jatin kumar";
const WHATSAPP_NUMBER = "917505090358";
const WEBHOOK_URL = "";
const $ = (sel, root=document) => root.querySelector(sel);
const esc = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money = amount => "₹" + Number(amount || 0).toLocaleString("en-IN", {maximumFractionDigits:0});
const today = () => new Date().toISOString().slice(0,10);
const daysBetween = (a,b) => Math.floor((new Date(b+"T00:00:00") - new Date(a+"T00:00:00"))/86400000);
const rankFor = n => n >= 90 ? "S-RANK MONARCH" : n >= 60 ? "S-RANK" : n >= 45 ? "A-RANK" : n >= 30 ? "B-RANK" : n >= 15 ? "C-RANK" : n >= 7 ? "D-RANK" : "E-RANK";
const ranks = ["E-RANK","D-RANK","C-RANK","B-RANK","A-RANK","S-RANK","S-RANK MONARCH"];
const defaultProducts = [
  {id:"p1",name:"Monarch Protein Bar",description:"Dark cacao, roasted almond and 20g of clean protein.",price:149,image:"https://images.unsplash.com/photo-1622483767028-3f66f32aef97?auto=format&fit=crop&w=900&q=85",nutrition:"Protein 20g · Carbs 18g · Fat 7g · 220 kcal"},
  {id:"p2",name:"Mana Shaker",description:"Leak-proof 700ml steel shaker built for the daily grind.",price:699,image:"https://images.unsplash.com/photo-1593095948071-474c5cc2989d?auto=format&fit=crop&w=900&q=85",nutrition:"700ml · BPA-free · Stainless steel"},
  {id:"p3",name:"Awakening Oats",description:"Slow-release rolled oats with chia and cacao nibs.",price:329,image:"https://images.unsplash.com/photo-1517673132405-a56a62b18caf?auto=format&fit=crop&w=900&q=85",nutrition:"Protein 13g · Carbs 54g · Fiber 9g · 340 kcal"}
];
const defaultVideos = [
  {id:"v1",title:"Full Body Foundations",tier:"Beginner (E-Rank)",duration:"22 min",muscles:"Full body · Form",video:"UBMk30rjy0o"},
  {id:"v2",title:"Strength & Conditioning",tier:"Moderate (B-Rank)",duration:"35 min",muscles:"Legs · Core",video:"IODxDxX7oi4"},
  {id:"v3",title:"High-Intensity Combat Circuit",tier:"Extreme (S-Rank)",duration:"28 min",muscles:"Full body · Cardio",video:"ml6cT4AZdqI"}
];
let accounts = JSON.parse(localStorage.getItem(USERS_KEY) || "[]");
let shop = JSON.parse(localStorage.getItem(SHOP_KEY) || "null") || {products:defaultProducts,videos:defaultVideos};
let session = JSON.parse(localStorage.getItem(SESSION_KEY) || "null");
let data = null;
let page = "overview", authMode = "login", authRole = "hunter", selectedDay = 1, activeModal = "", modalItem = null, cartOpen = false, chatOpen = false, chatHistory = [], stressLevel = 0, breathing = false;

function defaultData(name,email){return {profile:{name,email,height:170,weight:70,goal:"build",plan:"Awakened",startDate:today()},tasks:{},weightLogs:[{date:today(),weight:70}],calorieLogs:[],cycle:{start:today(),length:28,period:5,pcod:false,notes:""},sleepLogs:[],moods:[],schedule:{},cart:[],orders:[],planMeals:{}}}
function persist(){if(session?.role==="hunter"&&data)localStorage.setItem(APP_KEY+":data:"+session.email,JSON.stringify(data));localStorage.setItem(USERS_KEY,JSON.stringify(accounts));localStorage.setItem(SHOP_KEY,JSON.stringify(shop));}
function loadData(user){const raw=localStorage.getItem(APP_KEY+":data:"+user.email);data=raw?JSON.parse(raw):defaultData(user.name,user.email);if(!data.profile)data=defaultData(user.name,user.email);}
function currentDay(){return Math.max(1,Math.min(90,daysBetween(data.profile.startDate||today(),today())+1))}
function dayTasks(day){return data.tasks[day]||[false,false,false]}
function completedDays(){return Object.values(data.tasks).filter(t=>t.filter(Boolean).length===3).length}
function activeRank(){return rankFor(completedDays())}
function totalTaskCount(){return Object.values(data.tasks).reduce((n,t)=>n+t.filter(Boolean).length,0)}
function statValues(){const n=totalTaskCount();return {strength:Math.min(99,8+Math.floor(n*.7)),agility:Math.min(99,10+Math.floor(n*.55)),vitality:Math.min(99,12+Math.floor(n*.65)),discipline:Math.min(99,5+Math.floor(n*.85))}}
function setRoute(to){page=to;activeModal="";render();window.scrollTo(0,0)}
function saveAndRender(){persist();render()}
function icon(key){return ({overview:"⌂",awakening:"◈",wellness:"⌁",cycle:"◌",workouts:"↗",diet:"✳",store:"▣",membership:"◇",admin:"⌘"})[key]||"•"}
function navItems(){return session?.role==="admin"?[{id:"admin",label:"System Console"}]:[{id:"overview",label:"Overview"},{id:"awakening",label:"Awakening 90"},{id:"wellness",label:"Wellness"},{id:"cycle",label:"Cycle & Recovery"},{id:"workouts",label:"Dungeons"},{id:"diet",label:"Diet Protocol"},{id:"store",label:"Guild Store"},{id:"membership",label:"Membership"}]}
function shell(content,title){
 const nav=navItems().map(item=>`<button class="nav-item ${page===item.id?"active":""}" data-route="${item.id}"><span class="nav-icon">${icon(item.id)}</span><span>${item.label}</span></button>`).join("");
 const hunter=session?.role==="hunter";
 const rank=hunter?activeRank():"SYSTEM ADMIN";
 return `<div class="app-layout"><aside class="sidebar"><a class="brand" href="#"><span class="brand-mark">⌁</span><span class="brand-name">HUNTER FIT PRO<span>AWAKENING SYSTEM</span></span></a><div class="nav-label">${hunter?"Hunter interface":"Administrator"}</div><nav class="nav-list">${nav}</nav><div class="sidebar-bottom">${hunter?`<div class="rank-mini"><span class="eyebrow">Current rank</span><div class="rankline"><strong>${rank}</strong><small>DAY ${currentDay()} / 90</small></div><div class="progress" style="margin-top:11px"><i style="width:${Math.round(currentDay()/90*100)}%"></i></div></div>`:""}<div class="user-mini"><span class="avatar">${esc((session?.name||"H").slice(0,1).toUpperCase())}</span><div><strong>${esc(session?.name||"Hunter")}</strong><small>${hunter?rank:"ADMINISTRATOR"}</small></div><button class="text-btn" data-action="logout" style="margin-left:auto">Exit</button></div></div></aside><section class="main"><header class="topbar"><div><div class="eyebrow">${hunter?"HUNTER SYSTEM // ONLINE":"SYSTEM ADMIN // ONLINE"}</div><h1 class="page-title">${title}</h1></div><div class="top-actions">${hunter?`<span class="pill violet">${esc(data.profile.plan)} TIER</span><button class="icon-btn" data-action="open-cart">Cart · ${data.cart.reduce((n,x)=>n+x.qty,0)}</button>`:""}</div></header>${content}</section></div>${hunter?chatUI():""}`;
}
function chatUI(){return `<button class="chat-toggle" data-action="toggle-chat" aria-label="Open System Voice">⌁</button>${chatOpen?`<section class="chat-panel"><header class="chat-head"><div><strong>THE SYSTEM VOICE</strong><small>AI RECOVERY COMPANION</small></div><button class="text-btn" data-action="toggle-chat">×</button></header><div class="chat-messages" id="chat-messages"><div class="chat-msg">Hunter, your system is listening. Ask me about training, nutrition, or recovery.</div>${chatHistory.map(m=>`<div class="chat-msg ${m.role==="user"?"user":""}">${esc(m.content)}</div>`).join("")}</div><div class="quick-chips"><button class="chip" data-prompt="Build me a quick workout for today">Quick workout</button><button class="chip" data-prompt="How can I improve my recovery?">Recovery</button><button class="chip" data-prompt="Suggest a high-protein meal">High-protein meal</button></div><form class="chat-compose" data-form="chat"><input name="message" class="input" placeholder="Message the System Voice" required><button class="btn small">Send</button></form></section>`:""}`}
function pageTitle(){return ({overview:"Hunter Dashboard",awakening:"The 90-Day Awakening",wellness:"Health & Wellness",cycle:"Cycle & Recovery",workouts:"Dungeon Library",diet:"Diet Protocol",store:"Guild Store",membership:"Guild Membership",admin:"System Console"})[page]||"Hunter Dashboard"}
function render(){
 if(!session){$("#app").innerHTML=authView();return}
 if(session.role==="hunter"&&!data)loadData(session);
 const views={overview:overviewView,awakening:awakeningView,wellness:wellnessView,cycle:cycleView,workouts:workoutsView,diet:dietView,store:storeView,membership:membershipView,admin:adminView};
 let content=(views[page]||overviewView)();
 if(activeModal)content+=modalView();
 $("#app").innerHTML=shell(content,pageTitle());
 if(chatOpen){const m=$("#chat-messages");if(m)m.scrollTop=m.scrollHeight}
}
function authView(){return `<div class="auth-wrap"><section class="auth-intro"><div class="auth-mark">⌁</div><div class="eyebrow">YOUR SYSTEM HAS AWAKENED</div><h1>Become the<br><span>strongest</span><br>version.</h1><p>One quest at a time. Build your attributes, protect your recovery, and earn every rank in your own 90-day awakening.</p><div class="auth-stat"><div><strong>90</strong><span>days to ascend</span></div><div><strong>04</strong><span>core attributes</span></div><div><strong>06</strong><span>hunter ranks</span></div></div></section><section class="auth-box"><h2>Enter the System</h2><p>Choose your access level to continue.</p><div class="role-tabs"><button class="role-tab ${authRole==="hunter"?"active":""}" data-action="auth-role" data-role="hunter">Hunter</button><button class="role-tab ${authRole==="admin"?"active":""}" data-action="auth-role" data-role="admin">System Admin</button></div><div class="eyebrow" style="margin-bottom:10px">${authRole==="hunter"?"HUNTER PORTAL":"ADMIN PORTAL"}</div><h3 style="font-size:14px;margin:0 0 16px">${authMode==="login"?"Welcome back":"Create your profile"}</h3><form data-form="auth"><input type="hidden" name="role" value="${authRole}"><input type="hidden" name="mode" value="${authMode}"><div class="field" style="margin-bottom:11px"><label>${authRole==="hunter"?"Hunter name":"Administrator name"}</label><input name="name" autocomplete="name" ${authMode==="signup"?"required":""} placeholder="Your name"></div><div class="field" style="margin-bottom:11px"><label>Email address</label><input name="email" type="email" autocomplete="email" required placeholder="name@example.com"></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="${authMode==="login"?"current-password":"new-password"}" minlength="6" required placeholder="At least 6 characters"></div><button class="btn full" style="margin-top:17px">${authMode==="login"?"Enter as "+(authRole==="hunter"?"Hunter":"Admin"):"Create "+(authRole==="hunter"?"Hunter profile":"Admin account")}</button></form><button class="auth-switch" data-action="auth-mode">${authMode==="login"?"New here? Create an account":"Already registered? Sign in"}</button><div class="auth-note">Accounts and health data on this preview are stored in this browser. Client-side accounts are for demonstration and are not suitable for sensitive information or production authentication.</div></section></div>`}
function overviewView(){const day=currentDay(),tasks=dayTasks(day),stats=statValues(),done=tasks.filter(Boolean).length;const macros=macroTargets();return `<section class="card hero section"><div><span class="rank-badge">${activeRank()}</span><h2>Welcome back, ${esc(data.profile.name||"Hunter")}.</h2><p>Your awakening is in progress. Complete today's quests to strengthen your stats and move toward your next promotion.</p></div><div class="hero-side"><strong>DAY ${day}<small style="color:var(--muted);font:12px var(--mono)"> / 90</small></strong><span>${90-day} days to Monarch</span><div class="progress" style="width:150px;margin:10px 0 0 auto"><i style="width:${day/90*100}%"></i></div></div></section><section class="grid grid-4 section">${[["STRENGTH",stats.strength,"POWER OUTPUT"],["AGILITY",stats.agility,"MOVEMENT"],["VITALITY",stats.vitality,"RECOVERY"],["DISCIPLINE",stats.discipline,"QUEST CONSISTENCY"]].map((s,i)=>`<article class="card stat-card"><div class="stat-label">${s[0]}</div><div class="stat-value ${i===1?"stat-accent":""}">${String(s[1]).padStart(2,"0")}<span style="font:10px var(--mono);color:var(--muted)"> / 99</span></div><div class="stat-foot">${s[2]}</div></article>`).join("")}</section><section class="grid grid-2 section"><article class="card"><div class="section-head"><div><div class="eyebrow">DAILY QUEST · DAY ${day}</div><h2 style="margin-top:6px">Three actions. One stronger you.</h2></div><span class="pill cyan">${done}/3 complete</span></div>${["Workout completed","Water goal · 2.5L","Calorie target reached"].map((t,i)=>`<label class="task-row"><input class="check" type="checkbox" data-task="${i}" ${tasks[i]?"checked":""}><span class="task-info"><strong>${t}</strong><small>Complete to gain attribute XP</small></span><span class="task-xp">+1 XP</span></label>`).join("")}<div style="margin-top:16px"><div class="progress"><i style="width:${done/3*100}%"></i></div></div></article><article class="card"><div class="section-head"><div><div class="eyebrow">TODAY'S FUEL</div><h2 style="margin-top:6px">Macro protocol</h2></div><button class="text-btn" data-route="wellness">Open wellness →</button></div><div class="grid grid-3">${[["PROTEIN",macros.protein,"g"],["CARBS",macros.carbs,"g"],["FATS",macros.fat,"g"]].map(x=>`<div><div class="stat-label">${x[0]}</div><div class="stat-value" style="font-size:21px">${x[1]}<small style="font:10px var(--mono);color:var(--muted)"> ${x[2]}</small></div></div>`).join("")}</div><div style="margin-top:15px;padding-top:13px;border-top:1px solid var(--line);display:flex;justify-content:space-between"><span class="muted" style="font-size:10px">Recommended daily calories</span><strong class="mono">${macros.calories} kcal</strong></div></article></section><section class="grid grid-2 section"><article class="card"><div class="section-head"><div><div class="eyebrow">ASCENSION TRACK</div><h2 style="margin-top:6px">90-day progression</h2></div><button class="text-btn" data-route="awakening">Open quest log →</button></div><div class="progress"><i style="width:${completedDays()/90*100}%"></i></div><div style="display:flex;justify-content:space-between;margin-top:9px"><span class="muted" style="font-size:9px">${completedDays()} fully cleared days</span><span class="pill violet">${activeRank()}</span></div></article><article class="card"><div class="section-head"><div><div class="eyebrow">WEIGHT TREND</div><h2 style="margin-top:6px">Latest weigh-in</h2></div><button class="text-btn" data-route="wellness">Log weight →</button></div><div class="stat-value" style="margin:8px 0">${Number(data.profile.weight).toFixed(1)}<small style="font:11px var(--mono);color:var(--muted)"> kg</small></div><div class="stat-foot">${data.weightLogs.length} entries in your log</div></article></section>`}
function macroTargets(){const weight=Number(data.profile.weight)||70;const protein=Math.round(weight*(data.profile.goal==="cut"?2: data.profile.goal==="build"?1.9:1.6));const calories=Math.round(weight*(data.profile.goal==="cut"?27:data.profile.goal==="build"?34:30));const fat=Math.round(calories*.27/9);const carbs=Math.max(0,Math.round((calories-protein*4-fat*9)/4));return {protein,carbs,fat,calories}}
function awakeningView(){const now=currentDay(),day=Math.min(selectedDay,now),tasks=dayTasks(day),rank=activeRank();return `<section class="card hero section"><div><span class="eyebrow">SYSTEM QUEST LOG // ACTIVE</span><h2>Awakening Challenge</h2><p>Clear all three daily quests to mark a day complete. Each action adds XP to your core attributes.</p></div><div class="hero-side"><strong>${completedDays()}<small style="color:var(--muted);font:12px var(--mono)"> / 90</small></strong><span>days fully cleared</span></div></section><section class="grid grid-4 section">${[["CURRENT RANK",rank,"Promotion follows cleared days"],["DAYS ELAPSED",now,"Your challenge day"],["TOTAL XP",totalTaskCount(),"Quest actions completed"],["NEXT RANK",nextRankText(),"Keep your streak moving"]].map(x=>`<article class="card stat-card"><div class="stat-label">${x[0]}</div><div class="stat-value" style="font-size:18px;color:#cfb4ff">${x[1]}</div><div class="stat-foot">${x[2]}</div></article>`).join("")}</section><section class="card section"><div class="section-head"><div><div class="eyebrow">DAY SELECTOR</div><h2 style="margin-top:6px">90 days to ascend</h2></div><span class="pill cyan">Today · Day ${now}</span></div><div class="quest-grid">${Array.from({length:90},(_,i)=>{const n=i+1,t=dayTasks(n),isDone=t.filter(Boolean).length===3;return `<button class="quest-day ${isDone?"done":""} ${n===day?"current":""} ${n>now?"locked":""}" data-action="select-day" data-day="${n}" ${n>now?"disabled":""} title="Day ${n}${isDone?" · cleared":""}">${n}</button>`}).join("")}</div><div style="display:flex;gap:8px;margin-top:13px;flex-wrap:wrap"><span class="pill">Open</span><span class="pill violet">Cleared</span><span class="pill cyan">Selected</span></div></section><section class="grid grid-2 section"><article class="card"><div class="section-head"><div><div class="eyebrow">DAY ${day} // DAILY QUEST</div><h2 style="margin-top:6px">Clear your objectives</h2></div><span class="pill ${tasks.filter(Boolean).length===3?"violet":"cyan"}">${tasks.filter(Boolean).length}/3</span></div>${["Workout completed","Water goal · 2.5L","Calorie target reached"].map((x,i)=>`<label class="task-row"><input class="check" type="checkbox" data-task="${i}" data-day="${day}" ${tasks[i]?"checked":""}><span class="task-info"><strong>${x}</strong><small>+1 attribute XP on completion</small></span></label>`).join("")}</article><article class="card"><div class="section-head"><div><div class="eyebrow">PROMOTION LADDER</div><h2 style="margin-top:6px">Earn your rank</h2></div></div>${ranks.map((r,i)=>{const threshold=[0,7,15,30,45,60,90][i];return `<div class="task-row"><span class="rank-badge" style="min-width:${r.includes("MONARCH")?118:75}px;text-align:center">${r}</span><span class="task-info"><strong>${threshold===0?"Awakened":threshold+" cleared days"}</strong><small>${completedDays()>=threshold?"Rank unlocked":Math.max(0,threshold-completedDays())+" more cleared days to unlock"}</small></span><span class="${completedDays()>=threshold?"stat-accent":"muted"}">${completedDays()>=threshold?"✓":"·"}</span></div>`}).join("")}</article></section>`}
function bmiInfo(){const h=(Number(data.profile.height)||170)/100,w=Number(data.profile.weight)||70,bmi=w/(h*h);const category=bmi<18.5?"Low mass":bmi<25?"Optimal":bmi<30?"Critical mass":"High risk";return {bmi:bmi.toFixed(1),category,tone:bmi<18.5||bmi>=30?"red":bmi>=25?"violet":"cyan"}}
function weightBars(){const logs=[...data.weightLogs].slice(-8),values=logs.map(x=>Number(x.weight)||0),min=Math.min(...values),max=Math.max(...values);return logs.map(x=>{const height=max===min?54:Math.max(10,15+(Number(x.weight)-min)/(max-min)*80);return '<div class="chart-col"><div class="chart-bar" style="height:'+height+'%" title="'+Number(x.weight).toFixed(1)+' kg"></div><span>'+esc(x.date.slice(5))+'</span></div>'}).join("")}
function wellnessView(){const b=bmiInfo(),m=macroTargets();return `<section class="grid grid-3 section"><article class="card"><div class="eyebrow">BODY COMPOSITION</div><h2>BMI assessment</h2><div class="stat-value" id="bmi-value">${b.bmi}</div><span class="pill ${b.tone}" id="bmi-category">${b.category}</span><p class="muted">BMI is a screening measure, not a diagnosis.</p></article><article class="card"><div class="eyebrow">DAILY PROTEIN</div><div class="stat-value">${m.protein}<small> g</small></div><div class="stat-foot">Goal-based intake</div></article><article class="card"><div class="eyebrow">ENERGY TARGET</div><div class="stat-value">${m.calories}<small> kcal</small></div><div class="stat-foot">P ${m.protein}g · C ${m.carbs}g · F ${m.fat}g</div></article></section><section class="grid grid-2"><article class="card"><div class="eyebrow">PROFILE MEASUREMENTS</div><h2>Your baseline</h2><form data-form="profile" class="form-grid"><div class="field"><label>Height · cm</label><input name="height" type="number" value="${data.profile.height}" required></div><div class="field"><label>Weight · kg</label><input name="weight" type="number" step="0.1" value="${data.profile.weight}" required></div><div class="field"><label>Goal</label><select name="goal"><option value="build" ${data.profile.goal==="build"?"selected":""}>Build strength</option><option value="cut" ${data.profile.goal==="cut"?"selected":""}>Fat loss</option><option value="maintain" ${data.profile.goal==="maintain"?"selected":""}>Maintain</option></select></div><div style="display:flex;align-items:end"><button class="btn full">Save measurements</button></div></form><form data-form="calorie" class="form-grid" style="margin-top:20px"><div class="field"><label>Calories consumed today</label><input name="calories" type="number" placeholder="1850" required></div><div style="display:flex;align-items:end"><button class="btn secondary full">Log intake</button></div></form><div style="display:flex;justify-content:space-between;margin-top:12px;font-size:10px"><span class="muted">Today's intake</span><span class="mono">${data.calorieLogs.filter(x=>x.date===today()).reduce((n,x)=>n+x.calories,0)} / ${macroTargets().calories} kcal</span></div><div class="progress" style="margin-top:7px"><i style="width:${Math.min(100,data.calorieLogs.filter(x=>x.date===today()).reduce((n,x)=>n+x.calories,0)/macroTargets().calories*100)}%"></i></div></article><article class="card"><div class="eyebrow">WEIGHT MANAGEMENT</div><h2>Trend log</h2><div class="chart">${weightBars()}</div><div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Weight</th></tr></thead><tbody>${[...data.weightLogs].reverse().slice(0,5).map(x=>`<tr><td>${esc(x.date)}</td><td class="mono">${Number(x.weight).toFixed(1)} kg</td></tr>`).join("")}</tbody></table></div></article></section>`}
function cycleView(){const c=data.cycle,len=Math.max(21,Math.min(45,Number(c.length)||28)),elapsed=Math.max(0,daysBetween(c.start||today(),today())),day=elapsed%len+1,phase=day<=Math.min(5,Number(c.period)||5)?"Menstrual":day<len*.45?"Follicular":day<len*.62?"Ovulatory":"Luteal",phaseIndex=["Menstrual","Follicular","Ovulatory","Luteal"].indexOf(phase);return `<section class="grid grid-2 section"><article class="card"><div class="eyebrow">CYCLE PREDICTION</div><h2>${c.pcod?"PCOD support":"Cycle overview"}</h2><span class="pill cyan">${phase} phase</span><div class="cycle-ring"><div><strong>${day}</strong><span>DAY OF CYCLE</span></div></div><div class="phase-row">${[0,1,2,3].map(i=>`<div class="phase ${i===phaseIndex?"active":""}"></div>`).join("")}</div><p class="muted">Estimated next period: ${new Date(new Date(c.start||today()).getTime()+Math.ceil((elapsed+1)/len)*len*86400000).toLocaleDateString(undefined,{month:"short",day:"numeric"})}. Predictions are estimates, not medical advice.</p></article><article class="card"><div class="eyebrow">CYCLE SETTINGS</div><h2>Personalize your tracker</h2><form data-form="cycle" class="form-grid"><div class="field"><label>Last period start</label><input type="date" name="start" value="${esc(c.start)}" required></div><div class="field"><label>Average cycle · days</label><input type="number" name="length" value="${esc(c.length)}" min="21" max="45"></div><div class="field"><label>Period duration · days</label><input type="number" name="period" value="${esc(c.period)}" min="2" max="10"></div><label style="display:flex;align-items:center;gap:8px"><input class="check" type="checkbox" name="pcod" ${c.pcod?"checked":""}> PCOD / PCOS support view</label><div class="field full"><label>Recovery notes</label><textarea name="notes">${esc(c.notes)}</textarea></div><div class="field full"><button class="btn">Save cycle details</button></div></form></article></section><section class="grid grid-2"><article class="card"><div class="eyebrow">SLEEP & RECOVERY</div><h2>Log last night's sleep</h2><form data-form="sleep" class="form-grid"><div class="field"><label>Hours slept</label><input type="number" name="hours" min="0" max="24" step="0.25" placeholder="7.5" required></div><div class="field"><label>Recovery quality</label><select name="quality"><option>Restored</option><option>Fair</option><option>Low</option></select></div><div class="field full"><button class="btn secondary">Save recovery log</button></div></form><div class="stat-foot">Latest: ${data.sleepLogs[0]?esc(data.sleepLogs[0].hours)+" h · "+esc(data.sleepLogs[0].quality)+" · "+esc(data.sleepLogs[0].date):"No sleep logged yet"}</div></article><article class="card"><div class="eyebrow">MOOD & STRESS</div><h2>Check in with yourself</h2><form data-form="mood" class="form-grid"><div class="field"><label>Mood</label><select name="mood"><option>Focused</option><option>Steady</option><option>Low energy</option><option>Anxious</option><option>Overwhelmed</option></select></div><div class="field"><label>Stress · 1-5</label><select name="stress"><option value="1">1 · Calm</option><option value="2">2 · Light</option><option value="3">3 · Moderate</option><option value="4">4 · High</option><option value="5">5 · Overwhelmed</option></select></div><div class="field full"><label>What would support you today?</label><input name="note" placeholder="Optional note"></div><div class="field full"><button class="btn cyan">Log check-in</button></div></form><div class="stat-foot">${data.moods.length?"Latest: "+esc(data.moods[0].mood)+" · stress "+data.moods[0].stress+"/5":"Your check-ins stay on this device."}</div></article></section>`}
function videoCard(v){return `<article class="card video-card" data-tier="${esc(v.tier)}"><div class="video-frame"><iframe src="https://www.youtube-nocookie.com/embed/${encodeURIComponent(v.video)}" title="${esc(v.title)}" loading="lazy" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture" allowfullscreen></iframe></div><div class="video-info"><h3>${esc(v.title)}</h3><div class="video-meta"><span class="pill">${esc(v.tier.split(" ")[0])}</span><span>${esc(v.duration)}</span><span>${esc(v.muscles)}</span></div></div></article>`}
function workoutsView(){const tiers=["Beginner (E-Rank)","Moderate (B-Rank)","Extreme (S-Rank)"];return `<section class="section"><div class="section-head"><div><div class="eyebrow">DUNGEON LIBRARY</div><h2 style="margin-top:6px">Train with intent</h2></div><select class="input" id="tier-filter" style="width:auto"><option>All tiers</option>${tiers.map(t=>`<option>${t}</option>`).join("")}</select></div><div class="product-grid" id="video-list">${shop.videos.map(videoCard).join("")}</div></section><section class="card section"><div class="eyebrow">WEEKLY DUNGEON SCHEDULE</div><h2>Build your training week</h2><form data-form="schedule" class="form-grid" style="grid-template-columns:1fr 1fr auto"><div class="field"><label>Training day</label><select name="day">${["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"].map(x=>`<option>${x}</option>`).join("")}</select></div><div class="field"><label>Assign workout</label><select name="video">${shop.videos.map(v=>`<option value="${esc(v.id)}">${esc(v.title)}</option>`).join("")}</select></div><div style="display:flex;align-items:end"><button class="btn">Assign</button></div></form><div class="day-schedule" style="margin-top:14px">${["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday","Sunday"].map(day=>{const entry=data.schedule[day],v=shop.videos.find(x=>x.id===entry?.id);const item=entry&&v?`<small>${esc(v.title)}</small><label style="display:flex;gap:5px;align-items:center;font-size:8px;color:var(--muted)"><input class="check" type="checkbox" data-schedule-day="${day}" ${entry.done?"checked":""}> Cleared</label>`:`<small class="muted">Rest / recovery</small>`;return `<article class="schedule-day"><strong>${day.slice(0,3).toUpperCase()}</strong>${item}</article>`}).join("")}</div></section>`}
function meals(){const g=data.profile.goal;return g==="cut"?[["BREAKFAST","Greek yogurt, berries & overnight oats","420 kcal"],["LUNCH","Grilled tofu bowl, greens & brown rice","560 kcal"],["SNACK","Apple with almond butter","210 kcal"],["DINNER","Lentil curry with roasted vegetables","610 kcal"]]:g==="build"?[["BREAKFAST","Eggs, oats, banana & nut butter","620 kcal"],["LUNCH","Chicken or tofu, rice & greens","760 kcal"],["SNACK","Protein shake and a banana","340 kcal"],["DINNER","Salmon or paneer, potatoes & vegetables","680 kcal"]]:[["BREAKFAST","Oats, seasonal fruit & two eggs","520 kcal"],["LUNCH","Balanced grain bowl with lean protein","660 kcal"],["SNACK","Cottage cheese or hummus with fruit","260 kcal"],["DINNER","Dal, vegetables & roti","620 kcal"]]}
function dietView(){const m=macroTargets(),plan=meals();return `<section class="card hero section"><div><span class="eyebrow">PERSONALIZED FUEL PLAN</span><h2>${data.profile.goal==="cut"?"Lean & steady":data.profile.goal==="build"?"Strength & growth":"Performance & balance"}</h2><p>Daily suggestions shaped around your goal and body-weight protein target. Adapt portions to your appetite and needs.</p></div><div class="hero-side"><strong>${m.calories}<small style="font:11px var(--mono);color:var(--muted)"> kcal</small></strong><span>daily target · ${m.protein}g protein</span></div></section><section class="card section"><div class="eyebrow">TODAY'S MEAL SCHEDULE</div><h2>A simple daily rhythm</h2>${plan.map(x=>`<div class="food-row"><span class="food-time">${x[0]}</span><div><strong>${x[1]}</strong><p>Flexible serving · prioritize the protein source</p></div><span class="food-kcal">${x[2]}</span></div>`).join("")}</section><section class="grid grid-2"><article class="card"><div class="eyebrow">MACRO TARGETS</div><h2>Your daily split</h2>${[["Protein",m.protein,"#7c3aed"],["Carbohydrates",m.carbs,"#06b6d4"],["Fats",m.fat,"#ef4444"]].map(x=>`<div style="margin:13px 0"><div style="display:flex;justify-content:space-between;font-size:10px;margin-bottom:6px"><span>${x[0]}</span><span class="mono">${x[1]} g</span></div><div class="progress"><i style="width:${Math.min(100,x[1]*4)}%;background:${x[2]}"></i></div></div>`).join("")}</article><article class="card"><div class="eyebrow">ADJUST YOUR PLAN</div><h2>Update your goal</h2><p class="muted">Your meal suggestions and macro targets change with your wellness profile. Set an approach that feels sustainable.</p><button class="btn secondary" data-route="wellness">Update wellness profile</button></article></section>`}
