function storeView(){return `<section class="section"><div class="section-head"><div><div class="eyebrow">GUILD SUPPLY // VERIFIED FUEL</div><h2 style="margin-top:6px">The Hunter's essentials</h2></div><button class="btn secondary" data-action="open-cart">Open cart · ${data.cart.reduce((n,x)=>n+x.qty,0)}</button></div><div class="product-grid">${shop.products.map(productCard).join("")}</div></section>`}
function membershipView(){const plans=[["Awakened","Free","90-day quest log · Core health tools · Workout library","Current tier"],["Hunter Guild","₹499","Everything in Awakened · Expanded plans · Guild store access","Select Pro"],["Monarch Tier","₹999","Everything in Hunter Guild · Advanced recovery insights · Priority System Voice","Select Elite"]];return `<section class="section"><div class="eyebrow">GUILD MEMBERSHIP</div><h2>Choose your tier</h2><p class="muted">Select a plan to update your local membership profile. No payment is processed in this preview.</p><div class="grid grid-3" style="margin-top:16px">${plans.map((p,i)=>`<article class="card ${i===2?"glow":""}"><div class="eyebrow">TIER 0${i+1}</div><h2 style="font-size:17px;margin:9px 0">${p[0]}</h2><div class="stat-value" style="font-size:25px">${p[1]}<small style="font:10px var(--mono);color:var(--muted)">${i?" / month":""}</small></div><p class="muted" style="font-size:10px;line-height:1.8;min-height:74px">${p[2]}</p><button class="btn ${i===0?"secondary":""} full" data-action="plan" data-plan="${p[0]}">${data.profile.plan===p[0]?"Current tier":i===0?"Stay Awakened":p[3]}</button></article>`).join("")}</div></section>`}
function adminView(){const hunters=accounts.filter(x=>x.role==="hunter");const quests=hunters.reduce((n,x)=>{const d=JSON.parse(localStorage.getItem(APP_KEY+":data:"+x.email)||"null");return n+(d?Object.values(d.tasks||{}).reduce((a,t)=>a+t.filter(Boolean).length,0):0)},0);return `<section class="grid grid-4 section">${[["REGISTERED HUNTERS",hunters.length],["QUESTS CLEARED",quests],["CATALOG ITEMS",shop.products.length],["WORKOUT LINKS",shop.videos.length]].map(x=>`<article class="card stat-card"><div class="stat-label">${x[0]}</div><div class="stat-value">${x[1]}</div><div class="stat-foot">LOCAL PREVIEW DATA</div></article>`).join("")}</section><section class="grid grid-2 section"><article class="card"><div class="eyebrow">STORE MANAGEMENT</div><h2>Add a product</h2><form data-form="admin-product" class="form-grid"><div class="field"><label>Product name</label><input name="name" required></div><div class="field"><label>Cost · INR</label><input name="price" type="number" min="0" required></div><div class="field full"><label>Description</label><textarea name="description" required></textarea></div><div class="field full"><label>Image URL</label><input name="image" type="url" required></div><div class="field full"><label>Nutritional values</label><input name="nutrition" required></div><div class="field full"><button class="btn">Add to catalog</button></div></form></article><article class="card"><div class="eyebrow">DUNGEON MANAGEMENT</div><h2>Add a workout link</h2><form data-form="admin-video" class="form-grid"><div class="field full"><label>Workout title</label><input name="title" required></div><div class="field full"><label>YouTube URL or video ID</label><input name="video" required></div><div class="field"><label>Tier</label><select name="tier"><option>Beginner (E-Rank)</option><option>Moderate (B-Rank)</option><option>Extreme (S-Rank)</option></select></div><div class="field"><label>Duration</label><input name="duration" required></div><div class="field full"><label>Target muscle groups</label><input name="muscles" required></div><div class="field full"><button class="btn cyan">Add video to library</button></div></form></article></section><section class="card section"><div class="eyebrow">LIVE STORE CATALOG</div><h2>Manage products</h2><div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Price</th><th>Nutrition</th><th>Actions</th></tr></thead><tbody>${shop.products.map(p=>`<tr><td>${esc(p.name)}</td><td class="mono">${money(p.price)}</td><td>${esc(p.nutrition)}</td><td><button class="btn small secondary" data-action="edit-product" data-id="${esc(p.id)}">Edit</button> <button class="btn small danger" data-action="delete-product" data-id="${esc(p.id)}">Remove</button></td></tr>`).join("")}</tbody></table></div></section><section class="card section"><div class="eyebrow">WORKOUT LIBRARY LINKS</div><h2>Manage dungeon videos</h2><div class="table-wrap"><table class="table"><thead><tr><th>Workout</th><th>Tier</th><th>Duration</th><th>Targets</th><th>Actions</th></tr></thead><tbody>${shop.videos.map(v=>`<tr><td>${esc(v.title)}</td><td>${esc(v.tier)}</td><td>${esc(v.duration)}</td><td>${esc(v.muscles)}</td><td><button class="btn small secondary" data-action="edit-video" data-id="${esc(v.id)}">Edit</button> <button class="btn small danger" data-action="delete-video" data-id="${esc(v.id)}">Remove</button></td></tr>`).join("")}</tbody></table></div></section><section class="card section"><div class="eyebrow">WORKOUT LIBRARY LINKS</div><h2>Manage dungeon videos</h2><div class="table-wrap"><table class="table"><thead><tr><th>Workout</th><th>Tier</th><th>Duration</th><th>Targets</th><th>Actions</th></tr></thead><tbody>${shop.videos.map(v=>`<tr><td>${esc(v.title)}</td><td>${esc(v.tier)}</td><td>${esc(v.duration)}</td><td>${esc(v.muscles)}</td><td><button class="btn small secondary" data-action="edit-video" data-id="${esc(v.id)}">Edit</button> <button class="btn small danger" data-action="delete-video" data-id="${esc(v.id)}">Remove</button></td></tr>`).join("")}</tbody></table></div></section><section class="card"><div class="eyebrow">HUNTER ROSTER</div><h2>Registered consumer profiles</h2><div class="table-wrap"><table class="table"><thead><tr><th>Hunter</th><th>Email</th><th>Plan</th><th>Quest actions</th></tr></thead><tbody>${hunters.map(u=>{const d=JSON.parse(localStorage.getItem(APP_KEY+":data:"+u.email)||"null")||defaultData(u.name,u.email);return `<tr><td>${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(d.profile.plan)}</td><td class="mono">${Object.values(d.tasks||{}).reduce((n,t)=>n+t.filter(Boolean).length,0)}</td></tr>`}).join("")||`<tr><td colspan="4">No hunter profiles registered yet.</td></tr>`}</tbody></table></div></section>`}
function subtotal(){return data.cart.reduce((sum,item)=>sum+(shop.products.find(p=>p.id===item.id)?.price||0)*item.qty,0)}
function cartModal(){if(!data.cart.length)return `<div class="empty">Your cart is empty. Add something from the Guild Store.</div><button class="btn secondary full" data-action="close-modal">Back to store</button>`;const rows=data.cart.map(item=>{const p=shop.products.find(x=>x.id===item.id);if(!p)return "";return `<div class="order-line"><span><strong>${esc(p.name)}</strong><br><small class="muted">${money(p.price)} each</small></span><span class="mono"><button class="text-btn" data-action="qty" data-id="${p.id}" data-delta="-1">−</button> ${item.qty} <button class="text-btn" data-action="qty" data-id="${p.id}" data-delta="1">+</button> <button class="text-btn" style="color:#ff8a90" data-action="remove-cart" data-id="${p.id}">×</button></span><strong class="mono">${money(p.price*item.qty)}</strong></div>`}).join("");return rows+`<div class="order-total"><span>Subtotal</span><span class="mono">${money(subtotal())}</span></div><button class="btn full" style="margin-top:17px" data-action="checkout">Continue to checkout</button>`}
function checkoutModal(){const total=subtotal(),upi=`upi://pay?pa=${encodeURIComponent(UPI_ID)}&pn=${encodeURIComponent(SHOP_NAME)}&mc=0000&mode=02&purpose=00&am=${total.toFixed(2)}&cu=INR`,qr="https://api.qrserver.com/v1/create-qr-code/?size=240x240&margin=5&data="+encodeURIComponent(upi);const rows=data.cart.map(item=>{const p=shop.products.find(x=>x.id===item.id);return p?`<div class="order-line"><span>${esc(p.name)} × ${item.qty}</span><strong class="mono">${money(p.price*item.qty)}</strong></div>`:""}).join("");return `<div class="checkout-layout"><article class="card"><div class="field"><label>Name for the order (optional)</label><input id="order-name" placeholder="Your name"></div><h3 style="font-size:12px;margin:20px 0 7px">Order summary</h3>${rows}<div class="order-total"><span>Total</span><span class="mono">${money(total)}</span></div></article><article class="card qr-card"><div class="eyebrow">UPI PAYMENT · ${esc(UPI_ID)}</div><img src="${qr}" alt="UPI QR code for ${money(total)} payment"><p>Scan and pay using any UPI app. After paying, tap below to confirm your order.</p><button class="btn cyan full" data-action="confirm-order">Confirm Order on WhatsApp</button><p style="font-size:8px;margin-bottom:0">WhatsApp opens with your order details. Payment confirmation is handled by the seller.</p></article></div>`}

function productModal(){const p=shop.products.find(x=>x.id===modalItem);if(!p)return "";return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" data-stop><button class="icon-btn modal-close" data-action="close-modal">×</button><img src="${esc(p.image)}" alt="${esc(p.name)}" style="width:100%;height:180px;object-fit:cover;border-radius:9px"><div class="eyebrow" style="margin-top:15px">NUTRITION BREAKDOWN</div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.description)}</p><div class="card" style="padding:12px;margin:14px 0;font-size:11px">${esc(p.nutrition)}</div><div class="product-foot"><strong class="price">${money(p.price)}</strong><button class="btn" data-action="add-cart" data-id="${esc(p.id)}">Add to cart</button></div></section></div>`}
function editProductModal(){const p=shop.products.find(x=>x.id===modalItem);if(!p)return "";return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" data-stop><button class="icon-btn modal-close" data-action="close-modal">×</button><div class="eyebrow">CATALOG EDITOR</div><h2>Edit product</h2><form data-form="edit-product" class="form-grid"><input type="hidden" name="id" value="${esc(p.id)}"><div class="field"><label>Name</label><input name="name" value="${esc(p.name)}" required></div><div class="field"><label>Price · INR</label><input name="price" type="number" value="${esc(p.price)}" required></div><div class="field full"><label>Description</label><textarea name="description">${esc(p.description)}</textarea></div><div class="field full"><label>Image URL</label><input name="image" value="${esc(p.image)}" required></div><div class="field full"><label>Nutrition</label><input name="nutrition" value="${esc(p.nutrition)}" required></div><div class="field full"><button class="btn">Save product</button></div></form></section></div>`}
function breathingModal(){return `<div class="modal-backdrop"><section class="modal" style="text-align:center"><button class="icon-btn modal-close" data-action="stop-breathing">×</button><div class="eyebrow">SYSTEM RECOVERY PROTOCOL</div><h2>Reset your pace</h2><p class="muted">Follow the orb: inhale for 4 · hold for 4 · exhale for 6.</p><div class="breath-orb"><span id="breath-phase">BREATHE</span></div><p class="muted">Pause whenever you need. This is a grounding exercise, not medical care.</p><button class="btn secondary" data-action="stop-breathing">End protocol</button></section></div>`}
function editVideoModal(){const v=shop.videos.find(x=>x.id===modalItem);if(!v)return "";return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" data-stop><button class="icon-btn modal-close" data-action="close-modal">×</button><div class="eyebrow">DUNGEON EDITOR</div><h2>Edit workout link</h2><form data-form="edit-video" class="form-grid"><input type="hidden" name="id" value="${esc(v.id)}"><div class="field full"><label>Title</label><input name="title" value="${esc(v.title)}" required></div><div class="field full"><label>YouTube URL or video ID</label><input name="video" value="${esc(v.video)}" required></div><div class="field"><label>Tier</label><select name="tier"><option ${v.tier==="Beginner (E-Rank)"?"selected":""}>Beginner (E-Rank)</option><option ${v.tier==="Moderate (B-Rank)"?"selected":""}>Moderate (B-Rank)</option><option ${v.tier==="Extreme (S-Rank)"?"selected":""}>Extreme (S-Rank)</option></select></div><div class="field"><label>Duration</label><input name="duration" value="${esc(v.duration)}" required></div><div class="field full"><label>Target muscle groups</label><input name="muscles" value="${esc(v.muscles)}" required></div><div class="field full"><button class="btn">Save workout</button></div></form></section></div>`}
function modalView(){if(activeModal==="product")return productModal();if(activeModal==="editProduct")return editProductModal();if(activeModal==="editVideo")return editVideoModal();if(activeModal==="breathing")return breathingModal();let body=activeModal==="cart"?cartModal():checkoutModal();return `<div class="modal-backdrop" data-action="close-modal"><section class="modal" data-stop style="width:${activeModal==="checkout"?"min(740px,100%)":"min(520px,100%)"}"><button class="icon-btn modal-close" data-action="close-modal">×</button><div class="eyebrow">${activeModal==="cart"?"GUILD CART":"ORDER CONFIRMATION"}</div><h2>${activeModal==="cart"?"Your order":"Review & pay"}</h2>${body}</section></div>`}
async function passwordRecord(password,salt){const saltBytes=salt?Uint8Array.from(atob(salt),c=>c.charCodeAt(0)):crypto.getRandomValues(new Uint8Array(16));const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(password),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:saltBytes,iterations:100000,hash:"SHA-256"},key,256);return {salt:btoa(String.fromCharCode(...saltBytes)),hash:Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,"0")).join("")}}
function showAuthError(message){const form=$("[data-form='auth']");let box=$("#auth-error");if(!box){box=document.createElement("p");box.id="auth-error";box.style.cssText="color:#ff9da3;font-size:10px;margin:12px 0 0";form?.append(box)}box.textContent=message}
function beginBreathing(){activeModal="breathing";breathing=true;render();const phases=[["INHALE",4000],["HOLD",4000],["EXHALE",6000]];let i=0;const tick=()=>{if(!breathing)return;const target=$("#breath-phase");if(target)target.textContent=phases[i][0];const delay=phases[i][1];i=(i+1)%phases.length;window.breathTimer=setTimeout(tick,delay)};tick()}
function closeBreathing(){breathing=false;clearTimeout(window.breathTimer);activeModal="";render()}
function setTask(day,index,checked){const tasks=[...dayTasks(day)];tasks[index]=checked;data.tasks[day]=tasks;persist();render()}
function addToCart(id){const item=data.cart.find(x=>x.id===id);if(item)item.qty++;else data.cart.push({id,qty:1});persist();render()}
function orderMessage(name){const lines=data.cart.map(item=>{const p=shop.products.find(x=>x.id===item.id);return p?"• "+p.name+" × "+item.qty+" — "+money(p.price*item.qty):""}).filter(Boolean);return ["HUNTER FIT PRO — ORDER","Name: "+(name||"Not provided"),"",...lines,"","Total: "+money(subtotal()),"Date: "+new Date().toLocaleString()].join("\n")}
function confirmOrder(){const name=$("#order-name")?.value.trim()||"";const items=data.cart.map(i=>{const p=shop.products.find(x=>x.id===i.id);return p?{name:p.name,quantity:i.qty,unit_price:p.price}:null}).filter(Boolean);const total=subtotal(),createdAt=new Date().toISOString(),message=orderMessage(name);data.orders.unshift({name,items,total,createdAt});data.cart=[];persist();const target=WHATSAPP_NUMBER?"https://wa.me/"+WHATSAPP_NUMBER+"?text="+encodeURIComponent(message):"https://wa.me/?text="+encodeURIComponent(message);window.open(target,"_blank","noopener,noreferrer");if(WEBHOOK_URL){fetch(WEBHOOK_URL,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name:name||null,items,total,createdAt})}).catch(()=>{})}activeModal="";render()}
async function askCoach(text){const question=text.trim();if(!question)return;chatHistory.push({role:"user",content:question});render();let reply="I couldn't reach the System Voice just now. For health concerns or a personal plan, check in with a qualified professional.";try{if(window.websim?.chat?.completions){const completion=await window.websim.chat.completions.create({messages:[{role:"system",content:"You are The System Voice, a supportive fitness and recovery coach for Hunter Fit Pro. Give concise, practical, nonjudgmental guidance about training, food, hydration, sleep, and stress. Do not diagnose or prescribe. Encourage a clinician for medical symptoms, pregnancy, PCOD/PCOS decisions, eating disorders, or persistent pain. Avoid extreme restriction and unsafe exercise advice. Personal context: goal="+data.profile.goal+", weight="+data.profile.weight+" kg."},...chatHistory.slice(-10)]});reply=completion.content||reply}}catch(error){console.warn("System Voice unavailable",error)}chatHistory.push({role:"assistant",content:reply});render()}
async function handleSubmit(event){const form=event.target.closest("form[data-form]");if(!form)return;event.preventDefault();const kind=form.dataset.form,fd=new FormData(form),v=Object.fromEntries(fd.entries());if(kind==="auth"){const role=v.role,email=v.email.trim().toLowerCase(),password=v.password;try{if(v.mode==="signup"){if(accounts.some(a=>a.email===email&&a.role===role)){showAuthError("An account for this email and access level already exists.");return}const record=await passwordRecord(password);const user={email,role,name:v.name.trim(),...record};accounts.push(user);session={email,role,name:user.name};localStorage.setItem(SESSION_KEY,JSON.stringify(session));if(role==="hunter"){data=defaultData(user.name,email);persist()}else persist();page=role==="admin"?"admin":"overview";selectedDay=1;render()}else{const user=accounts.find(a=>a.email===email&&a.role===role);if(!user){showAuthError("No matching account was found for this portal.");return}const check=await passwordRecord(password,user.salt);if(check.hash!==user.hash){showAuthError("Email or password is incorrect.");return}session={email,role,name:user.name};localStorage.setItem(SESSION_KEY,JSON.stringify(session));if(role==="hunter"){loadData(session);selectedDay=currentDay();page="overview"}else page="admin";render()}}catch(error){showAuthError("Unable to create or verify this account in the current browser.");console.error(error)}return}
 if(kind==="profile"){const previous=Number(data.profile.weight);data.profile.height=Number(v.height);data.profile.weight=Number(v.weight);data.profile.goal=v.goal;if(previous!==data.profile.weight){const existing=data.weightLogs.findIndex(x=>x.date===today());if(existing>=0)data.weightLogs[existing].weight=data.profile.weight;else data.weightLogs.push({date:today(),weight:data.profile.weight})}saveAndRender()}
 if(kind==="calorie"){data.calorieLogs.push({date:today(),calories:Number(v.calories)});saveAndRender()}
 if(kind==="cycle"){data.cycle={start:v.start,length:Number(v.length),period:Number(v.period),pcod:fd.has("pcod"),notes:v.notes};saveAndRender()}
 if(kind==="sleep"){data.sleepLogs.unshift({date:today(),hours:Number(v.hours),quality:v.quality});saveAndRender()}
 if(kind==="mood"){const stress=Number(v.stress);data.moods.unshift({date:today(),mood:v.mood,stress,note:v.note});stressLevel=stress;persist();if(stress>=4)beginBreathing();else render()}
 if(kind==="schedule"){data.schedule[v.day]={id:v.video,done:false};saveAndRender()}
 if(kind==="admin-product"){shop.products.push({id:"p"+crypto.randomUUID(),name:v.name.trim(),description:v.description.trim(),price:Number(v.price),image:v.image.trim(),nutrition:v.nutrition.trim()});persist();render()}
 if(kind==="admin-video"){let id=v.video.trim();try{const u=new URL(id);id=u.searchParams.get("v")||u.pathname.split("/").filter(Boolean).pop()||id}catch{}id=id.replace(/[^a-zA-Z0-9_-]/g,"");if(id.length<6||id.length>15){form.insertAdjacentHTML("beforeend","<p style='color:#ff9da3;font-size:10px'>Enter a valid YouTube video URL or ID.</p>");return}shop.videos.push({id:"v"+crypto.randomUUID(),title:v.title.trim(),tier:v.tier,duration:v.duration.trim(),muscles:v.muscles.trim(),video:id});persist();render()}
 if(kind==="edit-product"){const p=shop.products.find(x=>x.id===v.id);if(p)Object.assign(p,{name:v.name.trim(),price:Number(v.price),description:v.description.trim(),image:v.image.trim(),nutrition:v.nutrition.trim()});activeModal="";persist();render()}
 if(kind==="edit-video"){let id=v.video.trim();try{const u=new URL(id);id=u.searchParams.get("v")||u.pathname.split("/").filter(Boolean).pop()||id}catch{}id=id.replace(/[^a-zA-Z0-9_-]/g,"");const video=shop.videos.find(x=>x.id===v.id);if(video&&id.length>=6&&id.length<=15)Object.assign(video,{title:v.title.trim(),video:id,tier:v.tier,duration:v.duration.trim(),muscles:v.muscles.trim()});activeModal="";persist();render()}
 if(kind==="chat"){form.reset();askCoach(v.message)}
}
document.addEventListener("submit",handleSubmit);
document.addEventListener("input",event=>{const form=event.target.closest("form[data-form=\"profile\"]");if(!form)return;const h=Number(form.elements.height.value)/100,w=Number(form.elements.weight.value);if(!h||!w)return;const bmi=w/(h*h),category=bmi<18.5?"Low mass":bmi<25?"Optimal":bmi<30?"Critical mass":"High risk",tone=bmi<18.5||bmi>=30?"red":bmi>=25?"violet":"cyan",value=$("#bmi-value"),badge=$("#bmi-category");if(value)value.textContent=bmi.toFixed(1);if(badge){badge.textContent=category;badge.classList.remove("red","violet","cyan");badge.classList.add(tone)}});
document.addEventListener("change",event=>{const t=event.target;if(t.matches("[data-task]")){setTask(Number(t.dataset.day||currentDay()),Number(t.dataset.task),t.checked);return}if(t.matches("[data-schedule-day]")){const entry=data.schedule[t.dataset.scheduleDay];if(entry){entry.done=t.checked;persist();render()}return}if(t.id==="tier-filter"){document.querySelectorAll("[data-tier]").forEach(card=>card.hidden=t.value!=="All tiers"&&card.dataset.tier!==t.value)}});
document.addEventListener("click",event=>{const target=event.target;if(target.closest("[data-stop]")&&!target.closest("[data-action]"))return;const route=target.closest("[data-route]");if(route){const next=route.dataset.route;if(navItems().some(x=>x.id===next))setRoute(next);return}const prompt=target.closest("[data-prompt]");if(prompt){askCoach(prompt.dataset.prompt);return}const el=target.closest("[data-action]");if(!el)return;const a=el.dataset.action;
 if(a==="auth-role"){authRole=el.dataset.role;render()}
 if(a==="auth-mode"){authMode=authMode==="login"?"signup":"login";render()}
 if(a==="logout"){session=null;data=null;page="overview";activeModal="";localStorage.removeItem(SESSION_KEY);render()}
 if(a==="toggle-chat"){chatOpen=!chatOpen;render()}
 if(a==="select-day"){const n=Number(el.dataset.day);if(n<=currentDay()){selectedDay=n;render()}}
 if(a==="open-cart"){activeModal="cart";render()}
 if(a==="close-modal"){activeModal="";render()}
 if(a==="checkout"){if(data.cart.length){activeModal="checkout";render()}}
 if(a==="product-detail"){modalItem=el.dataset.id;activeModal="product";render()}
 if(a==="edit-product"){modalItem=el.dataset.id;activeModal="editProduct";render()}
 if(a==="edit-video"){modalItem=el.dataset.id;activeModal="editVideo";render()}
 if(a==="delete-video"){const id=el.dataset.id;shop.videos=shop.videos.filter(x=>x.id!==id);for(const [day,entry] of Object.entries(data?.schedule||{}))if(entry.id===id)delete data.schedule[day];persist();render()}
 if(a==="add-cart"){addToCart(el.dataset.id)}
 if(a==="buy-now"){const item=data.cart.find(x=>x.id===el.dataset.id);if(item)item.qty++;else data.cart.push({id:el.dataset.id,qty:1});persist();activeModal="checkout";render()}
 if(a==="remove-cart"){data.cart=data.cart.filter(x=>x.id!==el.dataset.id);persist();render()}
 if(a==="qty"){const item=data.cart.find(x=>x.id===el.dataset.id);if(item)item.qty+=Number(el.dataset.delta);data.cart=data.cart.filter(x=>x.qty>0);persist();render()}
 if(a==="delete-product"){shop.products=shop.products.filter(x=>x.id!==el.dataset.id);persist();render()}
 if(a==="plan"){data.profile.plan=el.dataset.plan;saveAndRender()}
 if(a==="confirm-order"){confirmOrder()}
 if(a==="stop-breathing"){closeBreathing()}
});
document.addEventListener("keydown",event=>{if(event.key==="Escape"&&activeModal){if(activeModal==="breathing")closeBreathing();else{activeModal="";render()}}});
if(session){if(session.role==="hunter"){loadData(session);selectedDay=currentDay();page="overview"}else page="admin"}
render();
function nextRankText(){const thresholds=[7,15,30,45,60,90],i=thresholds.findIndex(x=>completedDays()<x);return i<0?"Monarch attained":`${thresholds[i]-completedDays()} days to ${ranks[i+1]}`}
